SET IDENTITY_INSERT dbo.[users] OFF;

SET IDENTITY_INSERT dbo.[programs] ON;
INSERT dbo.[programs] ([id],[name],[slug],[description],[is_active],[created_at]) VALUES
(1,N'CEFR B1',N'cefr-b1',N'Diễn đạt trải nghiệm, xử lý tình huống quen thuộc và viết văn bản liên kết ở trình độ B1. Viết đoạn văn rõ ý; mô tả trải nghiệm và giải thích lý do bằng ngôn ngữ thông dụng.',1,DATEADD(MINUTE,0,DATEADD(DAY,-98,@SeedNow))),
(2,N'CEFR B2',N'cefr-b2',N'Hiểu nội dung phức tạp, lập luận rõ ràng và giao tiếp độc lập ở trình độ B2. So sánh quan điểm, nêu ưu nhược điểm và dẫn chứng; chú ý liên kết và độ chính xác.',1,DATEADD(MINUTE,0,DATEADD(DAY,-98,@SeedNow))),
(3,N'IELTS 6.0',N'ielts-6-0',N'Củng cố kỹ năng cần thiết cho mục tiêu IELTS 6.0 qua bài luyện theo dạng thức. Xác định từ khóa, tránh sai dạng từ, trả lời đủ yêu cầu đề. Điểm phần mềm là điểm luyện tập, không quy đổi trực tiếp sang band IELTS.',1,DATEADD(MINUTE,0,DATEADD(DAY,-98,@SeedNow))),
(4,N'IELTS 6.5',N'ielts-6-5',N'Phát triển đọc hiểu, nghe chi tiết, viết có cấu trúc và diễn đạt tự nhiên cho mục tiêu 6.5. Luyện paraphrase, tổ chức đoạn văn, dùng dẫn chứng phù hợp và quản lý thời gian.',1,DATEADD(MINUTE,0,DATEADD(DAY,-98,@SeedNow))),
(5,N'IELTS 7.0',N'ielts-7-0',N'Nâng độ chính xác, chiều sâu lập luận và khả năng xử lý văn bản học thuật. Chú ý sắc thái ý nghĩa, từ đồng nghĩa theo ngữ cảnh, hedging và phát triển luận điểm.',1,DATEADD(MINUTE,0,DATEADD(DAY,-98,@SeedNow))),
(6,N'IELTS 7.5+',N'ielts-7-5-plus',N'Rèn tính linh hoạt ngôn ngữ, lập luận thuyết phục và xử lý các câu hỏi khó. Phân tích giả định, tổng hợp quan điểm, dùng collocation chính xác và tránh khẳng định quá mức.',1,DATEADD(MINUTE,0,DATEADD(DAY,-98,@SeedNow))),
(7,N'Luyện thi chuyên Anh',N'chuyen-anh',N'Củng cố cấu trúc nâng cao, từ vựng, biến đổi câu, đọc hiểu và viết cho kỳ thi chuyên Anh. Giải thích lựa chọn ngữ pháp, so sánh phương án nhiễu và luyện biến đổi cấu trúc tương đương.',1,DATEADD(MINUTE,0,DATEADD(DAY,-98,@SeedNow))),
(8,N'Tiếng Anh THCS',N'tieng-anh-thcs',N'Nắm vững kiến thức căn bản và giao tiếp theo chủ đề gần gũi với học sinh THCS. Dùng câu đơn chính xác, luyện phát âm từ mới và kể về trường học, gia đình, sở thích.',1,DATEADD(MINUTE,0,DATEADD(DAY,-98,@SeedNow))),
(9,N'Tiếng Anh THPT',N'tieng-anh-thpt',N'Hệ thống kiến thức THPT; luyện đọc hiểu, ngữ pháp, từ vựng và kỹ năng làm bài. Xác định chức năng mệnh đề, liên kết ý và chọn từ đúng ngữ cảnh. Đọc kỹ yêu cầu trước khi trả lời.',1,DATEADD(MINUTE,0,DATEADD(DAY,-98,@SeedNow))),
(10,N'Tiếng Anh học thuật',N'tieng-anh-hoc-thuat',N'Phát triển đọc nghiên cứu, viết đoạn học thuật, diễn giải và trình bày ý tưởng có dẫn chứng. Phân biệt ý kiến và bằng chứng, diễn giải nguồn bằng ngôn ngữ của mình và trình bày lập luận có giới hạn.',1,DATEADD(MINUTE,0,DATEADD(DAY,-98,@SeedNow))),
(11,N'Tiếng Anh giao tiếp',N'tieng-anh-giao-tiep',N'Tự tin sử dụng tiếng Anh trong giao tiếp hàng ngày và công việc cơ bản. Thực hành nói thành tiếng, hỏi lại khi chưa rõ và phản hồi lịch sự. Nộp bản ghi âm hoặc bản chép lời để giáo viên nhận xét.',1,DATEADD(MINUTE,0,DATEADD(DAY,-98,@SeedNow)));
