wers":[{"id":1881,"question_id":1043,"content":"cautious","is_correct":0},{"id":1882,"question_id":1043,"content":"caution","is_correct":1},{"id":1883,"question_id":1043,"content":"cautiously","is_correct":0},{"id":1884,"question_id":1043,"content":"cautioning","is_correct":0}]},{"id":1044,"exercise_id":209,"content":"The evidence is not ___ to prove the claim. (suffice)","type":"fill_blank","points":1,"explanation":"Đáp án chấp nhận: sufficient. Kiểm tra thì, cấu trúc và dạng từ trong câu.","correct_text":"sufficient","order_index":4,"answers":[]},{"id":1045,"exercise_id":209,"content":"Dựa vào đoạn văn, nhận định sau đúng hay sai?\nAn kept every detail she knew in her presentation.","type":"true_false","points":1,"explanation":"Kiểm tra chi tiết trực tiếp trong đoạn văn về “Planning a presentation”.","correct_text":"","order_index":5,"answers":[{"id":1885,"question_id":1045,"content":"True","is_correct":0},{"id":1886,"question_id":1045,"content":"False","is_correct":1}]},{"id":1046,"exercise_id":210,"content":"It is essential that the data ___ checked carefully.","type":"multiple_choice","points":1,"explanation":"Cấu trúc giả định sau essential/recommend dùng động từ nguyên mẫu.","correct_text":"","order_index":1,"answers":[{"id":1887,"question_id":1046,"content":"is","is_correct":0},{"id":1888,"question_id":1046,"content":"are being","is_correct":0},{"id":1889,"question_id":1046,"content":"be","is_correct":1},{"id":1890,"question_id":1046,"content":"was","is_correct":0}]},{"id":1047,"exercise_id":210,"content":"The committee recommended that he ___ present.","type":"fill_blank","points":1,"explanation":"Đáp án: be. Đọc lại toàn bộ câu sau khi điền.","correct_text":"be","order_index":2,"answers":[]},{"id":1048,"exercise_id":210,"content":"Sắp xếp các từ thành câu hoàn chỉnh: every day / English / I / practise","type":"ordering","points":1,"explanation":"Câu khẳng định: chủ ngữ + động từ + tân ngữ + trạng ngữ. Chấp nhận có hoặc không có dấu chấm.","correct_text":"I