INSERT dbo.[learning_paths] ([id],[teacher_id],[program_id],[title],[description],[level],[estimated_duration],[is_published],[created_at]) VALUES
(1,2,1,N'Lộ trình CEFR B1 — từng bước tiến bộ',N'Diễn đạt trải nghiệm, xử lý tình huống quen thuộc và viết văn bản liên kết ở trình độ B1. Học lần lượt ba khóa, hoàn thành bài tập và xem phản hồi của giáo viên.',N'intermediate',90,1,DATEADD(MINUTE,0,DATEADD(DAY,-95,@SeedNow))),
(2,3,2,N'Lộ trình CEFR B2 — từng bước tiến bộ',N'Hiểu nội dung phức tạp, lập luận rõ ràng và giao tiếp độc lập ở trình độ B2. Học lần lượt ba khóa, hoàn thành bài tập và xem phản hồi của giáo viên.',N'advanced',90,1,DATEADD(MINUTE,0,DATEADD(DAY,-95,@SeedNow))),
(3,4,3,N'Lộ trình IELTS 6.0 — từng bước tiến bộ',N'Củng cố kỹ năng cần thiết cho mục tiêu IELTS 6.0 qua bài luyện theo dạng thức. Học lần lượt ba khóa, hoàn thành bài tập và xem phản hồi của giáo viên.',N'intermediate',90,1,DATEADD(MINUTE,0,DATEADD(DAY,-95,@SeedNow))),
(4,5,4,N'Lộ trình IELTS 6.5 — từng bước tiến bộ',N'Phát triển đọc hiểu, nghe chi tiết, viết có cấu trúc và diễn đạt tự nhiên cho mục tiêu 6.5. Học lần lượt ba khóa, hoàn thành bài tập và xem phản hồi của giáo viên.',N'intermediate',90,1,DATEADD(MINUTE,0,DATEADD(DAY,-95,@SeedNow))),
(5,6,5,N'Lộ trình IELTS 7.0 — từng bước tiến bộ',N'Nâng độ chính xác, chiều sâu lập luận và khả năng xử lý văn bản học thuật. Học lần lượt ba khóa, hoàn thành bài tập và xem phản hồi của giáo viên.',N'advanced',90,1,DATEADD(MINUTE,0,DATEADD(DAY,-95,@SeedNow))),
(6,7,6,N'Lộ trình IELTS 7.5+ — từng bước tiến bộ',N'Rèn tính linh hoạt ngôn ngữ, lập luận thuyết phục và xử lý các câu hỏi khó. Học lần lượt ba khóa, hoàn thành bài tập và xem phản hồi của giáo viên.',N'advanced',90,1,DATEADD(MINUTE,0,DATEADD(DAY,-95,@SeedNow))),
(7,8,7,N'Lộ trình Luyện thi chuyên Anh — từng bước tiến bộ',N'Củng cố cấu trúc nâng cao, từ vựng, biến đổi câu, đọc hiểu và viết cho kỳ thi chuyên Anh. Học lần lượt ba khóa, hoàn thành bài tập và xem phản hồi của giáo viên.',N'advanced',90,1,DATEADD(MINUTE,0,DATEADD(DAY,-95,@SeedNow))),
(8,9,8,N'Lộ trình Tiếng Anh THCS — từng bước tiến bộ',N'Nắm vững kiến thức căn bản và giao tiếp theo chủ đề gần gũi với học sinh THCS. Học lần lượt ba khóa, hoàn thành bài tập và xem phản hồi của giáo viên.',N'beginner',90,1,DATEADD(MINUTE,0,DATEADD(DAY,-95,@SeedNow))),
(9,10,9,N'Lộ trình Tiếng Anh THPT — từng bước tiến bộ',N'Hệ thống kiến thức THPT; luyện đọc hiểu, ngữ pháp, từ vựng và kỹ năng làm bài. Học lần lượt ba khóa, hoàn thành bài tập và xem phản hồi của giáo viên.',N'intermediate',90,1,DATEADD(MINUTE,0,DATEADD(DAY,-95,@SeedNow))),
(10,11,10,N'Lộ trình Tiếng Anh học thuật — từng bước tiến bộ',N'Phát triển đọc nghiên cứu, viết đoạn học thuật, diễn giải và trình bày ý tưởng có dẫn chứng. Học lần lượt ba khóa, hoàn thành bài tập và xem phản hồi của giáo viên.',N'advanced',90,1,DATEADD(MINUTE,0,DATEADD(DAY,-95,@SeedNow))),
(11,12,11,N'Lộ trình Tiếng Anh giao tiếp — từng bước tiến bộ',N'Tự tin sử dụng tiếng Anh trong giao tiếp hàng ngày và công việc cơ bản. Học lần lượt ba khóa, hoàn thành bài tập và xem phản hồi của giáo viên.',N'beginner',90,1,DATEADD(MINUTE,0,DATEADD(DAY,-95,@SeedNow)));
